custom_css:
@import url('https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Inter:wght@400;600;700;800&display=swap');
/* == palette: player + settings + fab + playlist modal == */
.mt-player, #mt-settings-modal, .mt-fab, .mt-pl-modal { --t-ink:#17140f; --t-bg:#2a2620; --t-panel:#201d18; --t-deep:#15120e; --t-cream:#efe7d6; --t-dim:#a89b82; --t-line:rgba(239,231,214,.22); --t-accent:#bc4a28; --t-accent-lite:#d96b3f; --t-accent-h:#9e3a1f; --mt-text:var(--t-cream); --mt-text-dim:var(--t-dim); --mt-text-on-accent:#fff3e0; --mt-overlay:rgba(12,10,7,.62); --mt-text-strong:var(--t-cream); --mt-divider:var(--t-line); --mt-modal-shadow:6px 6px 0 rgba(10,8,6,.55); --mt-pl-spotify-tab:var(--t-accent); --mt-pl-spotify-tab-text:#fff3e0; }
.mt-progress { --mt-slider-track:rgba(239,231,214,.24); --mt-slider-track-height:3px; --mt-slider-track-radius:2px; --mt-slider-progress:var(--t-accent); --mt-slider-thumb-size:13px; --mt-slider-thumb-bg:var(--t-cream); --mt-slider-thumb-bg-hover:var(--t-accent); --mt-slider-thumb-border:2px solid var(--t-deep); --mt-slider-thumb-radius:3px; --mt-slider-thumb-shadow:0 0 0 1px rgba(21,18,14,.85); }
.mt-volume { --mt-slider-track:rgba(239,231,214,.24); --mt-slider-track-height:3px; --mt-slider-track-radius:2px; --mt-slider-progress:var(--t-cream); --mt-slider-thumb-size:10px; --mt-slider-thumb-bg:var(--t-cream); --mt-slider-thumb-bg-hover:var(--t-accent); --mt-slider-thumb-border:none; --mt-slider-thumb-radius:2px; --mt-slider-thumb-shadow:none; }
/* == player shell == */
.mt-player { container-type:size; padding:34px 16px 12px; background-color:var(--t-bg); background-image:radial-gradient(140% 110% at 88% -12%, rgba(188,74,40,.22), transparent 55%), radial-gradient(rgba(239,231,214,.05) 1px, transparent 1.4px), repeating-linear-gradient(0deg, rgba(239,231,214,.045) 0 1px, transparent 1px 26px), repeating-linear-gradient(90deg, rgba(239,231,214,.045) 0 1px, transparent 1px 26px); background-size:auto, 9px 9px, auto, auto; border:1px solid var(--t-line); border-radius:10px; color:var(--t-cream); font-family:'Inter', sans-serif; box-shadow:4px 4px 0 rgba(10,8,6,.55); backdrop-filter:none; }
.mt-player * { font-family:inherit; }
.mt-player i { font-family:'Font Awesome 6 Free', 'Font Awesome 5 Free', FontAwesome; }
#moodtube-mini-player, #moodtube-mini-player *, #mt-settings-modal, #mt-settings-modal *, .mt-fab, .mt-fab *, .mt-pl-modal, .mt-pl-modal * { text-shadow:none; }
.mt-player-body { gap:12px; }
/* == header == */
.mt-player-header { top:13px; left:17px; right:96px; }
.mt-player-header-title { font-family:'Bebas Neue', 'Inter', sans-serif; font-size:17px; letter-spacing:3px; line-height:1; color:var(--t-cream); }
.mt-player-header-title::before { content:'\2660\00a0'; color:var(--t-accent-lite); }
.mt-player-status { margin-top:4px; font-size:10px; font-weight:700; letter-spacing:2px; text-transform:uppercase; color:var(--t-accent-lite); }
.mt-player-status::before { content:''; display:inline-block; width:6px; height:6px; margin-right:6px; border-radius:1px; background:var(--t-accent-lite); }
.mt-is-paused .mt-player-status { color:var(--t-cream); }
.mt-is-paused .mt-player-status::before { background:var(--t-cream); }
.mt-is-idle .mt-player-status { color:var(--t-dim); }
.mt-is-idle .mt-player-status::before { background:var(--t-dim); }
/* == cover: poker-chip vinyl == */
@keyframes mt-spin { to { rotate:360deg; } }
.mt-cover { position:relative; width:132px; height:132px; overflow:visible; border:3px solid var(--t-accent); border-radius:50%; background:var(--t-deep); box-shadow:4px 4px 0 rgba(10,8,6,.5); animation:mt-spin 26s linear infinite; animation-play-state:paused; }
.mt-is-playing .mt-cover { animation-play-state:running; }
.mt-cover::before { content:''; position:absolute; inset:1px; border-radius:50%; z-index:4; pointer-events:none; background:repeating-conic-gradient(from 8deg, rgba(239,231,214,.85) 0deg 10deg, transparent 10deg 30deg); -webkit-mask-image:radial-gradient(farthest-side, transparent calc(100% - 8px), #000 calc(100% - 7px)); mask-image:radial-gradient(farthest-side, transparent calc(100% - 8px), #000 calc(100% - 7px)); }
.mt-cover::after { content:''; position:absolute; inset:24%; border-radius:50%; border:1px dashed rgba(239,231,214,.35); z-index:4; pointer-events:none; }
.mt-cover-hole { width:12px; height:12px; border-radius:50%; background:var(--t-cream); box-shadow:0 0 0 2px var(--t-deep), 0 0 0 3px rgba(239,231,214,.4); z-index:3; }
/* == track info == */
.mt-track-info { position:relative; width:100%; padding:0 26px 0 4px; text-align:center; }
.mt-track-title { font-family:'Bebas Neue', 'Inter', sans-serif; font-size:21px; letter-spacing:1.5px; line-height:1.05; color:var(--t-cream); }
.mt-track-subtitle { margin-top:3px; font-size:10px; font-weight:600; letter-spacing:2px; text-transform:uppercase; color:var(--t-dim); }
.mt-btn-favorite { color:var(--t-dim); background:none; border:none; box-shadow:none; }
.mt-btn-favorite:hover { color:var(--t-cream); }
.mt-btn-favorite.mt-is-active { color:var(--t-accent-lite); }
/* == progress and volume == */
.mt-progress { display:flex; align-items:center; gap:8px; width:100%; }
.mt-volume { display:flex; align-items:center; gap:8px; width:100%; }
.mt-progress input, .mt-volume input { flex:1 1 auto; min-width:0; }
.mt-time-current, .mt-time-total { flex-shrink:0; min-width:26px; font-size:10px; font-weight:600; color:var(--t-dim); font-variant-numeric:tabular-nums; }
.mt-time-total { text-align:right; }
.mt-volume-low, .mt-volume-high { flex-shrink:0; font-size:11px; color:var(--t-dim); }
/* == controls == */
.mt-controls { gap:10px; justify-content:center; align-items:center; flex-wrap:nowrap; }
.mt-controls > .mt-btn { width:30px; height:30px; font-size:12px; padding:0; line-height:1; box-sizing:border-box; flex-shrink:0; display:flex; align-items:center; justify-content:center; border-radius:50%; border:1px solid var(--t-line); background:transparent; color:var(--t-cream); transition:translate .15s ease, background-color .15s ease, color .15s ease, border-color .15s ease; }
.mt-controls > .mt-btn:hover { background:var(--t-cream); border-color:var(--t-cream); color:var(--t-ink); translate:0 -1px; }
.mt-controls > .mt-btn:active { translate:0 1px; }
.mt-controls > .mt-btn-play { width:40px; height:40px; font-size:15px; background:var(--t-accent); border:2px solid var(--t-cream); color:var(--mt-text-on-accent); box-shadow:3px 3px 0 rgba(10,8,6,.55); }
.mt-controls > .mt-btn-play:hover { background:var(--t-accent-h); border-color:var(--t-cream); color:var(--mt-text-on-accent); translate:-1px -1px; box-shadow:4px 4px 0 rgba(10,8,6,.55); }
.mt-controls > .mt-btn-play:active { translate:1px 1px; box-shadow:1px 1px 0 rgba(10,8,6,.55); }
.mt-btn-play.fa-play { padding-left:2px; }
.mt-btn-ai.mt-is-busy { animation:mt-spin 1.1s linear infinite; }
/* == window buttons == 28px touch targets, evenly spaced, in line with the header */
#moodtube-mini-player .mt-window-btn { width: 28px; height: 28px; min-width: 28px; padding: 0; box-sizing: border-box; display: flex; align-items: center; justify-content: center; line-height: 1; top: 11px; font-size: 14px; }
#moodtube-mini-player .mt-window-btn.mt-btn-close { right: 14px; left: auto; }
#moodtube-mini-player .mt-window-btn.mt-btn-settings { right: 46px; left: auto; }
#moodtube-mini-player .mt-window-btn.mt-btn-search { right: 78px; left: auto; }
#moodtube-mini-player .mt-window-btn.mt-btn-lyrics { right: 110px; left: auto; }
#moodtube-mini-player .mt-panel { padding-top: 46px; }
#moodtube-mini-player .mt-panel-header-left { margin-right: 0; }
#moodtube-mini-player .mt-player-header-title { font-size: 10.5px; letter-spacing: 0.04em; }
/* == /window buttons == */
